(function(root){'use strict';const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),types=[];for(const i of'IE')for(const s of'SN')for(const t of'TF')for(const j of'JP')types.push(i+s+t+j);const key='yumao.release.initial.v4';
function initialValue(storageKey=key){try{return localStorage.getItem(storageKey)||''}catch{return''}}function saveInitial(v,storageKey=key){try{localStorage.setItem(storageKey,v)}catch{}}
function download(data,name,type='application/json;charset=utf-8'){const u=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1500)}
function radar(r,c){const cx=180,cy=151,R=99,pt=(i,v)=>{const t=-Math.PI/2+i*Math.PI/3;return[cx+Math.cos(t)*R*v,cy+Math.sin(t)*R*v]},rows=c.styleOrder.map(id=>r.styleScores.find(s=>s.id===id));return`<figure class="cr-chart cr-radar"><figcaption>你的爱情风格</figcaption><svg viewBox="0 0 360 305" role="img" aria-label="六种爱情风格游戏得分"><title>六种爱情风格游戏得分雷达图</title>${[.25,.5,.75,1].map(v=>`<polygon points="${rows.map((s,i)=>pt(i,v).join(',')).join(' ')}" fill="none" stroke="#dbe1d3"/>`).join('')}${rows.map((s,i)=>`<line x1="${cx}" y1="${cy}" x2="${pt(i,1)[0]}" y2="${pt(i,1)[1]}" stroke="#e3e8dc"/>`).join('')}<polygon points="${rows.map((s,i)=>pt(i,s.normalized).join(',')).join(' ')}" fill="#719c7438" stroke="#477454" stroke-width="2.5"/>${rows.map((s,i)=>`<circle cx="${pt(i,s.normalized)[0]}" cy="${pt(i,s.normalized)[1]}" r="4" fill="#477454"/><text x="${pt(i,1.32)[0]}" y="${pt(i,1.32)[1]}" text-anchor="middle" dominant-baseline="middle" fill="#49614d" font-size="14">${esc(c.styles.find(x=>x.id===s.id).name)}</text>`).join('')}</svg><div class="cr-score-grid">${rows.map(s=>`<div><span>${esc(c.styles.find(x=>x.id===s.id).name)}</span><strong>${Math.round(s.normalized*100)}<small>/100</small></strong></div>`).join('')}</div><p class="cr-note">本局风格得分，各自按满分折算；不表示人格概率。</p></figure>`}
function axisChart(r,c){return`<figure class="cr-chart cr-axis-chart"><figcaption>初始类型与本局倾向</figcaption><p class="cr-note">○ 初始类别　● 本局原始得分　＊ 游戏拓展</p>${r.axes.map(a=>`<div class="cr-axis-plot"><div class="cr-plot-label"><b>${c.axes[a.axis].join(' / ')}</b><span>${a.before} → <strong>${a.after}${a.adjusted?'＊':''}</strong></span></div><div class="cr-plot"><span>${c.axes[a.axis][0]}</span><div class="cr-plot-track"><i class="cr-plot-center"></i><i class="cr-plot-baseline" style="left:${a.before===c.axes[a.axis][0]?10:90}%"></i><i class="cr-plot-raw" style="left:${50+40*a.net/a.maxWeight}%" title="${a.net}/${a.maxWeight}"></i></div><span>${c.axes[a.axis][1]}</span></div></div>`).join('')}</figure>`}
function resultExport(r,answers){return{version:r.version,answers,initial:r.initial,romanticType:r.romanticType,scoreType:r.scoreType,adjustment:r.adjustment,style:r.primary.id,styleTitle:r.primary.title,styleScores:r.styleScores,axes:r.axes.map(({module,evidence,...a})=>a),message:r.message}}
function wrapText(ctx,text,x,y,width,lineHeight){let line='';for(const ch of text){if(ctx.measureText(line+ch).width>width&&line){ctx.fillText(line,x,y);y+=lineHeight;line=ch}else line+=ch}if(line){ctx.fillText(line,x,y);y+=lineHeight}return y}
function saveCard(r){
 const cv=document.createElement('canvas');cv.width=900;cv.height=2400;
 function paint(){const x=cv.getContext('2d');x.fillStyle='#f3f4eb';x.fillRect(0,0,900,cv.height);x.fillStyle='#fffef8';x.fillRect(45,45,810,cv.height-90);x.fillStyle='#5c765b';x.font='24px sans-serif';x.fillText('与猫 AGENT · 十二题恋爱报告',90,120);x.font='bold 43px sans-serif';x.fillStyle='#294a39';let y=wrapText(x,r.primary.title,90,205,720,62);x.font='27px sans-serif';x.fillStyle='#63765e';y=wrapText(x,r.primary.hook,90,y+25,720,43);x.fillStyle='#2f654c';x.font='bold 48px sans-serif';y+=70;x.fillText(r.initial+'  →  '+r.romanticType+(r.adjustment?'＊':''),90,y);y+=65;x.font='24px sans-serif';x.fillStyle='#4d6250';
 for(const a of r.axes){x.fillText(a.axis+'    '+a.before+' → '+a.after+(a.adjusted?'＊':''),90,y);const left=340,right=790,cy=y-9;x.fillStyle='#dfe6db';x.fillRect(left,cy-4,right-left,8);x.strokeStyle='#8293b4';x.lineWidth=3;x.beginPath();x.arc(left+(a.before===window.YUMAO_COMPLETE_DATA.axes[a.axis][0]?.1:.9)*(right-left),cy,8,0,Math.PI*2);x.stroke();x.fillStyle='#477454';x.beginPath();x.arc(left+(.5+.4*a.net/a.maxWeight)*(right-left),cy,8,0,Math.PI*2);x.fill();x.fillStyle='#4d6250';y+=52;}
 x.font='20px sans-serif';y=wrapText(x,'○ 初始类别   ● 本局原始得分   ＊ 游戏拓展',90,y,720,30);y+=25;x.font='25px sans-serif';y=wrapText(x,r.primary.intro.join(''),90,y,720,42);x.strokeStyle='#d4ddc9';x.beginPath();x.moveTo(90,y+15);x.lineTo(810,y+15);x.stroke();x.font='24px sans-serif';y=wrapText(x,r.message,90,y+65,720,40);x.font='20px sans-serif';x.fillStyle='#788573';y=wrapText(x,r.adjustment?'＊原始类型同初始类型，按原版游戏规则拓展一轴；原始得分不改。':'来自十二次故事选择的游戏画像。',90,y+35,720,30);y=wrapText(x,'游戏画像不代表心理诊断。shark7755.github.io/yumao-agent/cg-showcase-complete/',90,y+15,720,29);return y+65;}
 const height=paint();cv.height=Math.ceil(height);paint();const a=document.createElement('a');a.href=cv.toDataURL('image/png');a.download='与猫_十二题恋爱报告.png';a.click();}
function render(host,answers,opts={}){const c=root.YUMAO_COMPLETE_DATA,storageKey=opts.storageKey||key,initial=opts.initial||initialValue(storageKey),r=root.YumaoComplete.build(answers,initial,c);const home=opts.home?'<button class="secondary" data-complete-action="home">回到故事</button>':'<a href="../site/index.html">回到故事</a>';if(!r.ready){host.innerHTML=`<div class="complete-report"><div class="cr-top">${home}</div><section class="cr-card"><span class="eyebrow">与你的十二次选择，聊聊爱情</span><h1>${r.finished?'十二题已完成，看看恋爱里的你':'先完成十二道选择'}</h1><p>已选择 ${r.completed} / ${r.total} 幕。${r.finished?'填写初始MBTI，生成爱情风格、类型对比和恋爱寄语。':'每一次建议，都有故事里的回应。'}</p><label>初始MBTI <select data-complete-initial><option value="">请选择</option>${types.map(t=>`<option ${initial===t?'selected':''}>${t}</option>`).join('')}</select></label><button class="primary" data-complete-action="generate" ${!r.finished?'disabled':''}>生成我的恋爱报告</button><p class="cr-note">填写你之前测得或认同的类型，用于前后对比。</p></section></div>`;host.querySelector('[data-complete-action="generate"]').onclick=()=>{const v=host.querySelector('select').value;if(!v){host.querySelector('select').focus();return}saveInitial(v,storageKey);render(host,answers,{...opts,initial:v})};if(opts.home)host.querySelector('[data-complete-action="home"]').onclick=opts.home;return r}saveInitial(r.initial,storageKey);const p=r.primary;
host.innerHTML=`<div class="complete-report"><div class="cr-top">${home}<button class="secondary" data-complete-action="edit-initial">修改初始MBTI</button><button class="secondary" data-complete-action="card">保存分享卡</button></div><form class="cr-card cr-initial-editor" hidden><label>初始MBTI <select>${types.map(t=>`<option ${r.initial===t?'selected':''}>${t}</option>`).join('')}</select></label><div class="cr-controls"><button class="primary" type="submit">更新报告</button><button class="secondary" type="button" data-complete-action="cancel-initial">取消</button></div></form><header class="cr-hero"><span class="eyebrow">与你的十二次选择，认真聊聊爱情</span><p class="cr-kicker">${esc(p.name)} · ${p.en}</p><h1>${esc(p.title)}</h1><p class="cr-hook">${esc(p.hook)}</p><div class="cr-badges"><span>十二道选择已完成</span><span>恋爱 ${r.romanticType}${r.adjustment?'＊':''}</span></div>${r.close?`<p class="cr-note">你的选择也带有${esc(r.secondary.name)}的色彩。</p>`:''}</header><section class="cr-card"><span class="eyebrow">01 · 爱情风格与称号</span><h2>你适合怎样的恋爱</h2>${radar(r,c)}${p.intro.map(t=>`<p>${esc(t)}</p>`).join('')}${p.sections.map(([h,ps])=>`<h3>${esc(h)}</h3><p>${esc(ps.join(''))}</p>`).join('')}</section><section class="cr-card"><span class="eyebrow">02 · 恋爱MBTI与初始对比</span><h2>同样是你，靠近时也有不同</h2><div class="cr-type"><strong>${r.initial}</strong><span>→</span><strong>${r.romanticType}${r.adjustment?'<sup>＊</sup>':''}</strong></div>${axisChart(r,c)}${r.adjustment?'<p class="cr-note cr-tie">＊ 原始类型与初始相同，星号是一项游戏拓展方向；图中保留原始分数。</p>':''}${r.axes.map(a=>`<article class="cr-axis" data-axis="${a.axis}"><div class="cr-axis-head"><b>${a.before} → ${a.after}${a.adjusted?'＊':''}</b><span>${a.adjusted?'试试另一种相处方式':a.changed?'本局呈现不同方向':a.tie?'同分保留':'本局与初始同向'}</span></div><h3>${esc(a.module.title)}</h3><p>${a.adjusted?esc(c.practiceCopy[a.axis+'_'+a.after]):esc(a.module.text)}</p></article>`).join('')}</section><section class="cr-card"><span class="eyebrow">03 · 给你的恋爱寄语</span><h2>带走一句，留给下一次相处</h2><p class="cr-message">${esc(r.message)}</p></section><details class="cr-card cr-method"><summary>看看本局选择与得分</summary>${r.evidence.map(e=>`<p><b>第${e.chapter}段 · ${esc(e.title)}</b><br>${e.optionId} · ${esc(e.label)}</p>`).join('')}<p class="cr-note">六类得分按各类满分折算；主类型依次比较分数、强支持次数、支持题数，完全相同按固定顺序。MBTI合并主轴与辅助信号，同分先保留初始；四字母全同时，按最小归一化净分翻转一轴。原始得分不改动。</p>${r.axes.map(a=>`<p>${a.axis} 净分 ${a.net}/${a.maxWeight}：${a.evidence.map(e=>`第${e.chapter}段 ${e.direction}×${e.weight}`).join('，')}</p>`).join('')}<div class="cr-controls"><button class="secondary" data-complete-action="export">导出本局记录</button><button class="secondary" data-complete-action="print">打印／存为PDF</button></div></details><footer class="cr-footer">这是十二段故事里的游戏画像。四个字母之外，也留一点空间给真实的自己。</footer></div>`;
const ed=host.querySelector('.cr-initial-editor');host.querySelector('[data-complete-action="edit-initial"]').onclick=()=>{ed.hidden=false;ed.querySelector('select').focus()};host.querySelector('[data-complete-action="cancel-initial"]').onclick=()=>ed.hidden=true;ed.onsubmit=e=>{e.preventDefault();const v=ed.querySelector('select').value;saveInitial(v,storageKey);opts.onInitialChange?.(v);render(host,answers,{...opts,initial:v})};host.querySelector('[data-complete-action="card"]').onclick=()=>saveCard(r);host.querySelector('[data-complete-action="export"]').onclick=()=>download(resultExport(r,answers),'与猫_本局恋爱报告.json');host.querySelector('[data-complete-action="print"]').onclick=()=>root.print();if(opts.home)host.querySelector('[data-complete-action="home"]').onclick=opts.home;return r}
root.YumaoCompleteUI={render,types,resultExport};})(window);
